// Dedup error executions by id. First run seeds (no alerts); after that only new ones.
const resp = $input.first().json;
const rows = (resp && resp.data) || [];
const store = $getWorkflowStaticData('global');
if (!Array.isArray(store.seen)) store.seen = [];
const seen = new Set(store.seen);
const selfWfId = $workflow.id;
const firstRun = store.seeded !== true;
const out = [];
for (const e of rows) {
  const id = String(e.id);
  if (e.workflowId === selfWfId) { seen.add(id); continue; }  // never alert on the poller itself
  if (seen.has(id)) continue;
  seen.add(id);
  if (!firstRun) {
    out.push({ json: { execId: id, workflowId: e.workflowId, startedAt: e.startedAt } });
  }
}
store.seen = Array.from(seen).slice(-500);  // bound the memory
store.seeded = true;
return out;

// Build the alert from the enriched execution detail (Slack + email).
const d = $json || {};
const prev = $('Filter New Errors').item.json;
const execId = String(d.id || prev.execId || '');
const wfId = d.workflowId || prev.workflowId || '';
const wfName = (d.workflowData && d.workflowData.name) || 'unknown workflow';
let node = 'n/a', msg = '';
try {
  const rd = d.data && d.data.resultData;
  node = (rd && rd.lastNodeExecuted) || 'n/a';
  msg = (rd && rd.error && rd.error.message) || '';
} catch (e) {}
if (msg && msg.length > 500) msg = msg.slice(0, 500);
const errText = msg || '(no message captured)';
const link = 'https://your-n8n.example/workflow/' + wfId + '/executions/' + execId;
const text =
  ':warning: *n8n workflow error*\n' +
  '*Workflow:* ' + wfName + ' (`' + wfId + '`)\n' +
  '*Node:* ' + node + '\n' +
  '*Error:* ' + errText + '\n' +
  '*Execution:* <' + link + '|' + execId + '>';
const email_html =
  '<div style="font-family:Arial,Helvetica,sans-serif;font-size:14px;color:#1a1a1a;line-height:1.5">' +
  '<p><strong>n8n workflow error</strong></p>' +
  '<table style="border-collapse:collapse">' +
  '<tr><td style="padding:2px 10px 2px 0;color:#666">Workflow</td><td style="padding:2px 0"><strong>' + wfName + '</strong> (' + wfId + ')</td></tr>' +
  '<tr><td style="padding:2px 10px 2px 0;color:#666">Node</td><td style="padding:2px 0"><strong>' + node + '</strong></td></tr>' +
  '<tr><td style="padding:2px 10px 2px 0;color:#666">Error</td><td style="padding:2px 0">' + errText + '</td></tr>' +
  '<tr><td style="padding:2px 10px 2px 0;color:#666">Execution</td><td style="padding:2px 0"><a href="' + link + '">' + execId + '</a></td></tr>' +
  '</table></div>';
return { json: {
  slack_payload: { text },
  workflow: wfName, workflow_id: wfId, node: node, error: errText,
  exec_id: execId, link: link,
  email_subject: 'n8n workflow error: ' + wfName + ' (exec ' + execId + ')',
  email_html: email_html
}};
